// Flatten (WF04): Notion candidate query -> one item per job. Only ACTIVE + QC APPROVED jobs are ever enriched (re-checked here even though the query filters them).
const cfg = $('Config').first().json;
const plain = (a) => (a || []).map((x) => x.plain_text || '').join('');
const pv = (p) => { if (!p) return ''; switch (p.type) { case 'title': return plain(p.title); case 'rich_text': return plain(p.rich_text); case 'number': return p.number === null ? null : p.number; case 'select': return p.select ? p.select.name : ''; case 'url': return p.url || ''; case 'checkbox': return !!p.checkbox; case 'date': return p.date ? p.date.start : ''; case 'unique_id': return p.unique_id ? (p.unique_id.prefix ? p.unique_id.prefix + '-' : '') + p.unique_id.number : ''; default: return ''; } };
const r = $input.first().json;
if (!r || r.error || r.object === 'error' || !Array.isArray(r.results)) return [{ json: { _kind: 'meta', status: 'QUEUE_ERROR', errors: [{ stage: 'queue', type: 'notion_error', msg: String((r && ((r.error && r.error.message) || r.message)) || 'bad response').slice(0, 200) }] } }];
const unk = (v) => !v || v === 'Unknown';
const jobs = [];
r.results.forEach((pg) => {
  const P = pg.properties || {};
  const life = pv(P['Lifecycle Status']); const qc = pv(P['QC Decision']);
  if (life !== 'ACTIVE' || qc !== 'APPROVED') return;
  const cur = { jlpt: pv(P['JLPT Required']), lic: pv(P['License Required']), lic_type: pv(P['License Type']), exp: pv(P['Experience Required']), exp_min: pv(P['Experience Years Min']), basis: pv(P['Salary Basis']), hourly: pv(P['Effective Hourly Wage']), mmin: pv(P['Monthly Salary Min']), mmax: pv(P['Monthly Salary Max']), checked: pv(P['Enrichment Checked']), evidence: pv(P['Enrichment Evidence']) };
  const pri = unk(cur.jlpt) ? 1 : !cur.basis ? 2 : unk(cur.lic) ? 3 : unk(cur.exp) ? 4 : 5;
  jobs.push({ json: { _kind: 'job', page_id: pg.id, page_url: pg.url, mtg_job_id: pv(P['Job ID']), job_number: String(pv(P['Job Number']) || '').trim(), title: pv(P['Job Title']), company: String(pv(P['Company']) || '').trim(), source_url: pv(P['Source URL']), recruitability: pv(P['Recruitability']), lifecycle: life, qc, priority: pri, cur, errors: [] } });
});
if (!jobs.length) return [{ json: { _kind: 'meta', status: 'EMPTY_QUEUE', errors: [] } }];
jobs.sort((a, b) => a.json.priority - b.json.priority || String(a.json.cur.checked || '').localeCompare(String(b.json.cur.checked || '')));
return jobs.slice(0, Number(cfg.max_per_run) || 20);

// Extract (WF04): read the HelloWork page and extract JLPT / license / experience / salary basis DETERMINISTICALLY, each with the verbatim source line as evidence. Anything not explicitly stated stays Unknown (never No).
const cfg = $('Config').first().json;
const N = (s) => String(s || '').normalize('NFKC');
const toText = (h) => N(String(h || '').replace(/<script[\s\S]*?<\/script>/gi, '').replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|tr|li|h\d|table|dt|dd)>/gi, '\n').replace(/<[^>]+>/g, '\n').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/\n[ \t　]*(?=\n)/g, '').replace(/\n{2,}/g, '\n').trim());
const clip = (s, n) => String(s || '').slice(0, n);
const LABELS = ['年齢', '年齢制限範囲', '学歴', '必要な経験等', '必要な免許・資格', '賃金', '賃金形態', '就業時間', '休憩時間', '年間休日', '求人に関する特記事項', '仕事の内容', '雇用形態', '加入保険等', '通勤手当', '賞与', '昇給', '退職金', '時間外労働時間', '月平均時間外労働時間'];
const OVERSEAS_OK = [/海外(在住)?(の方|者)?(から|在住).{0,8}(応募|可|歓迎|OK)/, /(国外|海外)在住.{0,4}(可|OK|歓迎)/, /来日前.{0,12}(応募|面接|内定|選考)/, /(入国前|渡日前).{0,12}(応募|面接|内定|選考)/, /(海外|来日前).{0,20}オンライン面接|オンライン面接.{0,20}(海外|来日前)/];
const DOMESTIC = [/(海外|国外)在住.{0,4}(不可|不可能|NG)/, /国内(に)?在住(の方|者)?(のみ|限)/, /日本(国)?内に(在住|居住).{0,10}(方|者|必須)/, /在留カード.{0,12}(必須|をお持ちの方のみ)/];
const hit = (arr, t) => { for (const r of arr) { const m = t.match(r); if (m) return m[0].slice(0, 80); } return ''; };
const out = [];
const inputs = $input.all();
for (let k = 0; k < inputs.length; k++) {
  const it = inputs[k]; let job = {};
  try { job = $('Is Candidate?').itemMatching(k).json; } catch (e) { job = {}; }
  const errors = (job.errors || []).slice();
  const err = it.json && it.json.error; const html = (it.json && it.json.data) || '';
  const det = { state: 'OK', jlpt: 'Unknown', jlpt_ev: '', lic: 'Unknown', lic_ev: '', lic_type: '', exp: 'Unknown', exp_min: null, exp_ev: '', basis: '', hourly: null, mmin: null, mmax: null, basis_ev: '', overseas_hit: '', domestic_hit: '', notes: [] };
  let body = '';
  if (err) { det.state = /404|410|not found/i.test(String(err.message || err)) ? 'GONE' : 'UNREACHABLE'; errors.push({ stage: 'source_fetch', type: det.state, msg: String(err.message || err).slice(0, 200) }); }
  else if (typeof html !== 'string' || html.length < 3000) { det.state = 'UNREACHABLE'; errors.push({ stage: 'source_fetch', type: 'UNREACHABLE', msg: 'response too short' }); }
  else {
    const full = toText(html); const start = full.indexOf('の募集内容、仕事概要');
    if (/(掲載を終了|受付を終了|募集を終了|求人は終了|この求人は.{0,6}(終了|締め切)|ページが見つかりません)/.test(full.slice(0, 4000)) && start < 0) det.state = 'CLOSED_ON_SOURCE';
    body = (start >= 0 ? full.slice(start) : full).slice(0, 12000);
    const lines = body.split('\n').map((s) => s.trim()).filter((s) => s.length);
    const idx = (l) => lines.indexOf(l);
    const section = (l, max) => { const i = idx(l); if (i < 0) return []; const res = []; for (let q = i + 1; q < lines.length && res.length < (max || 4); q++) { if (LABELS.indexOf(lines[q]) >= 0) break; res.push(lines[q]); } return res; };
    // ---- JLPT (needs a Japanese-language context in the same line; conflicting levels -> Unknown)
    const levels = {}; let jEv = '';
    lines.forEach((l) => { if (!/日本語|JLPT|語学/.test(l)) return; const m = l.match(/(?:日本語能力試験|JLPT|日本語検定|日本語能力|日本語)[^\n]{0,24}?N\s*([1-5])/i) || l.match(/N\s*([1-5])\s*(以上|程度|レベル|相当|取得|合格|保持)/i); if (m) { levels['N' + m[1]] = levels['N' + m[1]] || clip(l, 120); } });
    const lk = Object.keys(levels);
    if (lk.length === 1) { det.jlpt = lk[0]; det.jlpt_ev = levels[lk[0]]; }
    else if (lk.length > 1) { det.notes.push('jlpt conflict: ' + lk.join('/')); }
    else { const nl = lines.find((l) => /日本語[^\n]{0,12}(不問|不要|問いません|必要ありません)/.test(l)); if (nl) { det.jlpt = 'None'; det.jlpt_ev = clip(nl, 120); } }
    // ---- License
    const ls = section('必要な免許・資格', 4); const lt = ls.join(' ');
    const anyNoLic = lines.find((l) => /(特別な)?(資格|免許)(や[^\n]{0,6})?は?(不要|不問)|(資格|免許)[^\n]{0,8}(不問|不要)/.test(l));
    const typeRe = /(普通自動車(?:第一種)?(?:運転)?免許(?:\([^)]{0,12}\))?|大型自動車(?:運転)?免許|中型自動車(?:運転)?免許|フォークリフト[^\s、。]{0,10}|介護福祉士|介護職員初任者研修|実務者研修|調理師|[^\s、。]{2,12}(?:技能講習|免許|資格))/;
    if (lt) {
      const tm = lt.match(typeRe);
      if (/(不問|不要|特になし|必要ありません)/.test(lt) && !/(必須)/.test(lt)) { det.lic = 'No'; det.lic_ev = clip(lt, 120); }
      else if (/(尚可|歓迎|あれば|優遇|望ましい)/.test(lt)) { det.lic = 'Preferred'; det.lic_ev = clip(lt, 120); det.lic_type = tm ? clip(tm[0], 60) : ''; }
      else if (/(必須|必要|要)/.test(lt.replace(/不要/g, '')) && tm) { det.lic = 'Yes'; det.lic_ev = clip(lt, 120); det.lic_type = clip(tm[0], 60); }
      else { det.notes.push('license section present but no explicit required/preferred/not-required wording'); }
    } else if (anyNoLic) { det.lic = 'No'; det.lic_ev = clip(anyNoLic, 120); }
    // ---- Experience (labelled field first)
    const es = section('必要な経験等', 1).join(' ');
    const expText = es || ''; let eev = es;
    if (expText) {
      const ym = expText.match(/([0-9]+)\s*年以上/);
      if (/(経験不問|未経験(者)?(歓迎|可|OK|大歓迎)|経験(は)?(問いません|不要))/.test(expText)) { det.exp = 'No'; det.exp_ev = clip(eev, 120); }
      else if (ym) { det.exp = 'Yes'; det.exp_min = Number(ym[1]); det.exp_ev = clip(eev, 120); }
      else if (/(経験者|経験必須|経験が必要|実務経験)/.test(expText) && /(必須|必要|経験者)/.test(expText) && !/(歓迎|優遇|尚可)/.test(expText)) { det.exp = 'Yes'; det.exp_ev = clip(eev, 120); }
      else det.notes.push('experience field present but not explicit: ' + clip(expText, 60));
    } else { const l = lines.find((x) => /(未経験(者)?(歓迎|OK|可)|経験不問)/.test(x)); if (l) { det.exp = 'No'; det.exp_ev = clip(l, 120); } }
    // ---- Salary basis
    const sb = (lines[idx('賃金形態') + 1] || '').replace(/,/g, '');
    if (idx('賃金形態') >= 0) {
      det.basis = /^時給/.test(sb) ? 'HOURLY' : /^日給/.test(sb) ? 'DAILY' : /^月給/.test(sb) ? 'MONTHLY' : /^(年俸|年収)/.test(sb) ? 'ANNUAL' : ''; det.basis_ev = clip(sb, 80);
      const hm = sb.match(/時給([0-9]{3,5})/); if (hm && det.basis === 'HOURLY') det.hourly = Number(hm[1]);
      const wl = (lines[idx('賃金') + 1] || '').replace(/,/g, ''); const wm = wl.match(/([0-9]{5,7})円?\s*[〜~]?\s*([0-9]{5,7})?/);
      if (wm && det.basis === 'MONTHLY') { det.mmin = Number(wm[1]); det.mmax = wm[2] ? Number(wm[2]) : Number(wm[1]); }
    }
    det.overseas_hit = hit(OVERSEAS_OK, body); det.domestic_hit = hit(DOMESTIC, body);
  }
  const needsAi = det.state === 'OK' && String(cfg.use_ai) !== 'false' && body.length > 300 && (det.jlpt === 'Unknown' || det.lic === 'Unknown' || det.exp === 'Unknown');
  out.push({ json: Object.assign({}, job, { det, errors, detail_text: det.state === 'OK' ? body : '', needs_ai: needsAi ? 'true' : 'false' }) });
}
return out;

// Prepare AI (WF04): AI may only EXTRACT the unresolved fields, with a verbatim quote. It never decides, infers or touches QC / company / overseas.
const cfg = $('Config').first().json;
const SYSTEM = `あなたは求人票の「抽出」専用エンジンです。求人票テキストに明記されている事実だけを抜き出します。推測・一般知識・補完は禁止。明記がなければ必ず "Unknown"。
出力はJSONオブジェクトのみ（前後の説明・コードフェンス禁止）。各項目の quote は求人票テキストからの一字一句そのままの抜粋（60字以内）。見つからなければ ""。
項目:
1. jlpt: 日本語能力試験の必要レベルが明記されていれば "N1"〜"N5"。日本語能力が不問と明記なら "None"。「日常会話ができる」等レベルの明記がないものは "Unknown"。
2. license: 免許・資格が必須と明記 → "Yes"、あれば尚可/歓迎/優遇 → "Preferred"、不問/不要と明記 → "No"、記載なし → "Unknown"。license_type に免許・資格の名称（原文のまま）。
3. experience: 経験不問/未経験歓迎と明記 → "No"、必須または年数の明記 → "Yes"、記載なし → "Unknown"。experience_years_min は「◯年以上」の数字（なければ null）。
スキーマ: {"jlpt":"","jlpt_quote":"","license":"","license_type":"","license_quote":"","experience":"","experience_years_min":null,"experience_quote":""}`;
return $input.all().map((it) => {
  const j = it.json; const want = []; if (j.det.jlpt === 'Unknown') want.push('jlpt'); if (j.det.lic === 'Unknown') want.push('license'); if (j.det.exp === 'Unknown') want.push('experience');
  const user = '求人番号: ' + j.job_number + '\n抽出が必要な項目: ' + want.join(', ') + '\n---求人票本文---\n' + String(j.detail_text || '').slice(0, 9000);
  return { json: Object.assign({}, j, { ai_req: { model: cfg.ai_model_enrich, max_tokens: 700, temperature: 0, system: SYSTEM, messages: [{ role: 'user', content: user }] } }) };
});

// Parse AI (WF04): AI output is DATA. A value is accepted only if its quote exists verbatim in the page AND the quote itself contains the evidence for that value. Otherwise Unknown.
const parseJson = (t) => { let s = String(t || '').trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim(); const a = s.indexOf('{'); const b = s.lastIndexOf('}'); if (a < 0 || b < a) return null; try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return null; } };
const N = (s) => String(s || '').normalize('NFKC').replace(/[\s　]+/g, '');
const out = [];
const inputs = $input.all();
for (let k = 0; k < inputs.length; k++) {
  const it = inputs[k]; let j = {};
  try { j = $('Prepare AI').itemMatching(k).json; } catch (e) { j = {}; }
  const errors = (j.errors || []).slice();
  const base = Object.assign({}, j, { ai_req: undefined, errors });
  const a = parseJson(it.json && it.json.content && it.json.content[0] && it.json.content[0].text);
  if ((it.json && it.json.error) || !a) { errors.push({ stage: 'ai_enrich', type: 'ai_error', msg: (it.json && it.json.error ? String(it.json.error.message || it.json.error) : 'unparseable JSON').slice(0, 200) }); out.push({ json: Object.assign(base, { ai: { ok: false, rejected: [] } }) }); continue; }
  const T = N(j.detail_text); const inSrc = (q) => { const x = N(q); return x.length >= 4 && T.indexOf(x) >= 0; };
  const ai = { ok: true, jlpt: 'Unknown', jlpt_ev: '', lic: 'Unknown', lic_ev: '', lic_type: '', exp: 'Unknown', exp_min: null, exp_ev: '', rejected: [] };
  const rej = (f, why) => ai.rejected.push(f + ': ' + why);
  const need = { jlpt: j.det.jlpt === 'Unknown', lic: j.det.lic === 'Unknown', exp: j.det.exp === 'Unknown' };
  // JLPT
  if (need.jlpt && a.jlpt && a.jlpt !== 'Unknown') {
    const q = N(a.jlpt_quote);
    if (!inSrc(a.jlpt_quote)) rej('jlpt', 'quote not in source');
    else if (/^N[1-5]$/.test(a.jlpt) && new RegExp(a.jlpt, 'i').test(q) && /日本語|JLPT|語学|能力/.test(q)) { ai.jlpt = a.jlpt; ai.jlpt_ev = String(a.jlpt_quote).slice(0, 120); }
    else if (a.jlpt === 'None' && /日本語/.test(q) && /(不問|不要|問いません|必要ありません)/.test(q)) { ai.jlpt = 'None'; ai.jlpt_ev = String(a.jlpt_quote).slice(0, 120); }
    else rej('jlpt', 'quote does not support value ' + a.jlpt);
  }
  // License
  if (need.lic && a.license && a.license !== 'Unknown') {
    const q = N(a.license_quote);
    if (!inSrc(a.license_quote)) rej('license', 'quote not in source');
    else if (!/(免許|資格|技能講習|研修|士)/.test(q)) rej('license', 'quote has no license wording');
    else if (a.license === 'No' && /(不問|不要|なし)/.test(q)) { ai.lic = 'No'; ai.lic_ev = String(a.license_quote).slice(0, 120); }
    else if (a.license === 'Preferred' && /(尚可|歓迎|あれば|優遇|望ましい)/.test(q)) { ai.lic = 'Preferred'; ai.lic_ev = String(a.license_quote).slice(0, 120); }
    else if (a.license === 'Yes' && /(必須|必要|要)/.test(q.replace(/不要/g, '')) && !/(尚可|歓迎|あれば|優遇)/.test(q)) { ai.lic = 'Yes'; ai.lic_ev = String(a.license_quote).slice(0, 120); }
    else rej('license', 'quote does not support value ' + a.license);
    if (ai.lic !== 'Unknown' && ai.lic !== 'No' && a.license_type && q.indexOf(N(a.license_type)) >= 0) ai.lic_type = String(a.license_type).slice(0, 60);
  }
  // Experience
  if (need.exp && a.experience && a.experience !== 'Unknown') {
    const q = N(a.experience_quote);
    if (!inSrc(a.experience_quote)) rej('experience', 'quote not in source');
    else if (a.experience === 'No' && /(未経験|経験不問|経験は問|経験不要)/.test(q)) { ai.exp = 'No'; ai.exp_ev = String(a.experience_quote).slice(0, 120); }
    else if (a.experience === 'Yes' && /経験/.test(q) && /(必須|必要|[0-9]+年以上|経験者)/.test(q) && !/(歓迎|優遇|尚可)/.test(q)) { ai.exp = 'Yes'; ai.exp_ev = String(a.experience_quote).slice(0, 120); const ym = q.match(/([0-9]+)年以上/); if (ym && Number(a.experience_years_min) === Number(ym[1])) ai.exp_min = Number(ym[1]); }
    else rej('experience', 'quote does not support value ' + a.experience);
  }
  out.push({ json: Object.assign(base, { ai }) });
}
return out;

// Enrich Diff (WF04): merge deterministic + validated-AI results, FILL ONLY UNKNOWN fields, never overwrite a known value, never downgrade. Builds the diff-only PATCH. Owns: JLPT / License / Experience / Salary Basis (+ hourly / monthly when empty). Does NOT touch QC, company, Recruitability, lifecycle, tier or Matching Ready.
const cfg = $('Config').first().json;
const clip = (s, n) => String(s === undefined || s === null ? '' : s).slice(0, n || 1900);
const unk = (v) => !v || v === 'Unknown';
const out = [];
for (const it of $input.all()) {
  const j = it.json; const det = j.det || { state: 'UNREACHABLE' }; const ai = j.ai || { ok: false, rejected: [] }; const cur = j.cur || {};
  const errors = (j.errors || []).slice(); const rows = []; const conflicts = [];
  const base = Object.assign({}, j); delete base.detail_text; delete base.needs_ai;
  if (det.state !== 'OK') { out.push({ json: Object.assign(base, { _kind: 'enriched', outcome: 'SOURCE_' + det.state, changed: [], rows, errors, needs_write: 'false', notion_patch_body: { properties: {} }, notion_sent: {} }) }); continue; }
  const pick = (f, dv, dev, av, aev) => { // returns {value, source, evidence}
    if (!unk(dv)) return { value: dv, source: 'DET', evidence: dev, conf: 'HIGH' };
    if (!unk(av)) return { value: av, source: 'AI', evidence: aev, conf: 'MEDIUM' };
    return { value: 'Unknown', source: '', evidence: '', conf: '' };
  };
  const F = { 'JLPT Required': pick('jlpt', det.jlpt, det.jlpt_ev, ai.jlpt, ai.jlpt_ev), 'License Required': pick('lic', det.lic, det.lic_ev, ai.lic, ai.lic_ev), 'Experience Required': pick('exp', det.exp, det.exp_ev, ai.exp, ai.exp_ev) };
  const have = { 'JLPT Required': cur.jlpt, 'License Required': cur.lic, 'Experience Required': cur.exp };
  const P = {}; const sent = {}; const changed = []; const newEv = {};
  const setSel = (k, v) => { P[k] = { select: { name: v } }; sent[k] = v; changed.push(k); };
  Object.keys(F).forEach((k) => {
    const c = F[k]; const h = have[k];
    if (c.value === 'Unknown') { rows.push({ field: k, old_value: h || '', new_value: 'Unknown', evidence: '', confidence: '', source: '', changed: 'false' }); return; }
    if (!unk(h) && h !== c.value) { conflicts.push(k + ': stored ' + h + ' vs source ' + c.value); rows.push({ field: k, old_value: h, new_value: c.value, evidence: clip(c.evidence, 200), confidence: c.conf, source: c.source, changed: 'false' }); return; }
    if (!unk(h) && h === c.value) { rows.push({ field: k, old_value: h, new_value: c.value, evidence: clip(c.evidence, 200), confidence: c.conf, source: c.source, changed: 'false' }); return; }
    setSel(k, c.value); newEv[k] = c.source + ' 「' + clip(c.evidence, 100) + '」';
    rows.push({ field: k, old_value: h || '', new_value: c.value, evidence: clip(c.evidence, 200), confidence: c.conf, source: c.source, changed: 'true' });
  });
  // License type / experience years: fill when empty and the matching field is (now) known
  const licVal = !unk(have['License Required']) ? have['License Required'] : F['License Required'].value;
  const ltype = det.lic_type || ai.lic_type || '';
  if (ltype && !cur.lic_type && (licVal === 'Yes' || licVal === 'Preferred') && F['License Required'].value !== 'Unknown') { P['License Type'] = { rich_text: [{ type: 'text', text: { content: clip(ltype, 60) } }] }; sent['License Type'] = clip(ltype, 60); changed.push('License Type'); rows.push({ field: 'License Type', old_value: '', new_value: clip(ltype, 60), evidence: clip(F['License Required'].evidence, 200), confidence: F['License Required'].conf, source: F['License Required'].source, changed: 'true' }); }
  const expMin = det.exp_min !== null && det.exp_min !== undefined ? det.exp_min : (ai.exp_min !== null && ai.exp_min !== undefined ? ai.exp_min : null);
  const expVal = !unk(have['Experience Required']) ? have['Experience Required'] : F['Experience Required'].value;
  if (expMin !== null && (cur.exp_min === null || cur.exp_min === '' || cur.exp_min === undefined) && expVal === 'Yes') { P['Experience Years Min'] = { number: expMin }; sent['Experience Years Min'] = expMin; changed.push('Experience Years Min'); rows.push({ field: 'Experience Years Min', old_value: '', new_value: String(expMin), evidence: clip(F['Experience Required'].evidence, 200), confidence: F['Experience Required'].conf, source: F['Experience Required'].source, changed: 'true' }); }
